ALTER TABLE `providerLocations` ADD CONSTRAINT `provider_locations_coordinates_chk` CHECK (`providerLocations`.`latitude` BETWEEN -90 AND 90 AND `providerLocations`.`longitude` BETWEEN -180 AND 180 AND (`providerLocations`.`accuracy` IS NULL OR `providerLocations`.`accuracy` BETWEEN 0 AND 10000));--> statement-breakpoint
ALTER TABLE `serviceRequests` ADD CONSTRAINT `service_requests_coordinates_pair_chk` CHECK ((`serviceRequests`.`latitude` IS NULL AND `serviceRequests`.`longitude` IS NULL) OR (`serviceRequests`.`latitude` IS NOT NULL AND `serviceRequests`.`longitude` IS NOT NULL AND `serviceRequests`.`latitude` BETWEEN -90 AND 90 AND `serviceRequests`.`longitude` BETWEEN -180 AND 180));